const express = require('express');
const app = express();

// Middleware to parse query parameters
app.use(express.urlencoded({ extended: true }));
app.use(express.json());

// Search endpoint with result highlighting
app.get('/search', (req, res) => {
  const query = req.query.q || '';
  const page = parseInt(req.query.page) || 1;
  const category = req.query.cat || 'all';

  // Simulate search results
  const results = [
    { title: 'Result 1', snippet: 'Lorem ipsum dolor sit amet' },
    { title: 'Result 2', snippet: 'Consectetur adipiscing elit' },
    { title: 'Result 3', snippet: 'Sed do eiusmod tempor incididunt' }
  ];

  // Build HTML response with search term reflected in page
  const html = `
    <!DOCTYPE html>
    <html lang="en">
    <head>
      <meta charset="UTF-8">
      <title>Search Results - ${category}</title>
      <link rel="stylesheet" href="/static/styles.css">
    </head>
    <body>
      <header>
        <nav>
          <a href="/">Home</a>
          <a href="/search">Search</a>
        </nav>
      </header>
      <main>
        <div class="search-container">
          <form action="/search" method="GET">
            <input type="text" name="q" value="${query}" placeholder="Search...">
            <input type="hidden" name="cat" value="${category}">
            <button type="submit">Search</button>
          </form>
        </div>
        <div class="results-info">
          <p>Showing results for: <strong>${query}</strong></p>
          <p>Category: ${category} | Page: ${page}</p>
        </div>
        <div class="results-list">
          ${results.map(r => `
            <div class="result-item">
              <h3>${r.title}</h3>
              <p>${r.snippet}</p>
            </div>
          `).join('')}
        </div>
        <div class="pagination">
          <a href="/search?q=${encodeURIComponent(query)}&page=${page - 1}&cat=${category}">Previous</a>
          <a href="/search?q=${encodeURIComponent(query)}&page=${page + 1}&cat=${category}">Next</a>
        </div>
      </main>
      <footer>
        <p>&copy; 2024 SearchApp</p>
      </footer>
    </body>
    </html>
  `;

  res.type('html').send(html);
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// Error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Internal Server Error');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
